style.css:
@-moz-document domain("youtube.com") {
.html5-video-player:not(.ad-showing) .ytp-play-progress {
    background: #080808 !important;
    box-shadow: 0 0 0 1px rgba(210, 210, 210, 0.48) !important;
  }

  .html5-video-player:not(.ad-showing) .ytp-progress-list {
    background: rgba(205, 205, 205, 0.25) !important;
  }

  .html5-video-player:not(.ad-showing) .ytp-load-progress {
    background: rgba(205, 205, 205, 0.24) !important;
  }

  /* The outer container keeps YouTube's own moving position. */
  .html5-video-player:not(.ad-showing) .ytp-scrubber-container {
    opacity: 1 !important;
  }

  .html5-video-player:not(.ad-showing) .ytp-scrubber-button {
    background: transparent !important;
    box-shadow: none !important;
    transform: none !important;
    overflow: visible !important;
  }

  .html5-video-player:not(.ad-showing) .ytp-scrubber-button::after {
    content: "";
    position: absolute;
    width: 34px;
    height: 34px;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -59%);
    background: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2240%22%20height%3D%2240%22%20viewBox%3D%220%200%2040%2040%22%3E%0A%3Cpolygon%20points%3D%2219.5%2C3.6%2026%2C4.3%2030.8%2C7.8%2034%2C12.6%2035.1%2C18.4%2034.2%2C25.2%2031.4%2C30%2025.7%2C34.1%2019%2C35%2012.8%2C33.5%207.9%2C30.1%204.8%2C24.4%204.1%2C18.6%205.4%2C12.4%208.7%2C7.6%2014%2C4.7%2019.5%2C3.6%22%20fill%3D%22%23080808%22%20stroke%3D%22%23a8a8a8%22%20stroke-width%3D%221.2%22%20stroke-linejoin%3D%22round%22%2F%3E%0A%3Cg%20fill%3D%22none%22%20stroke%3D%22%23eeeeea%22%20stroke-width%3D%222.1%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%0A%3Cpolyline%20points%3D%2213.8%2C14.6%2013.2%2C16.5%2013.8%2C17.3%22%2F%3E%3Cpolyline%20points%3D%2224.2%2C14.9%2023.6%2C16.7%2024.1%2C17.5%22%2F%3E%3Cpolyline%20points%3D%2211.8%2C27.1%2014.2%2C24.8%2016.9%2C23.5%2020.1%2C23.2%2023.3%2C24.2%2026.1%2C26.7%22%2F%3E%0A%3C%2Fg%3E%3C%2Fsvg%3E") center / contain no-repeat !important;
    pointer-events: none;
  }

  .html5-video-player:not(.ad-showing) .ytp-decorated-scrubber-button {
    display: none !important;
  }
}
